const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const paths={home:'M3 10l9-7 9 7v10H3z M9 20v-7h6v7',new:'M12 5v14 M5 12h14',products:'M4 4h6v6H4z M14 4h6v6h-6z M4 14h6v6H4z M14 14h6v6h-6z',orders:'M6 3h12v18H6z M9 8h6 M9 12h6 M9 16h4',style:'M12 3l9 5-9 5-9-5z M3 12l9 5 9-5 M3 16l9 5 9-5',admin:'M4 20V10 M10 20V4 M16 20v-8 M22 20H2',help:'M12 16h.01 M9 8a3 3 0 116 0c0 2-3 2-3 5 M22 12a10 10 0 11-20 0 10 10 0 0120 0',settings:'M4 7h16 M4 17h16 M8 4v6 M16 14v6',upload:'M12 16V3 M7 8l5-5 5 5 M4 14v7h16v-7',arrow:'M5 12h14 M14 7l5 5-5 5',check:'M5 12l4 4L20 5',download:'M12 3v13 M7 11l5 5 5-5 M4 17v4h16v-4',spark:'M12 3l2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.style}"/></svg>`;
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plural=(n,one,few,many)=>n%10===1&&n%100!==11?one:n%10>=2&&n%10<=4&&(n%100<12||n%100>14)?few:many;
const uid=()=>Date.now().toString(36)+Math.random().toString(36).slice(2,6);
const sampleSvg=`<svg xmlns="http://www.w3.org/2000/svg" width="700" height="650" viewBox="0 0 700 650"><defs><linearGradient id="b" x2="0" y2="1"><stop stop-color="#eee9dd"/><stop offset="1" stop-color="#d9d4c5"/></linearGradient><filter id="s"><feGaussianBlur stdDeviation="15"/></filter></defs><rect width="700" height="650" fill="url(#b)"/><ellipse cx="350" cy="560" rx="225" ry="30" fill="#aaa58f" opacity=".35" filter="url(#s)"/><g fill="#f8f6ed" stroke="#d1ccbe" stroke-width="3"><path d="M130 330l410-30 50 65-410 40z"/><path d="M130 330v160l50 65V405z"/><path d="M180 405l410-40v160l-410 30z"/><path d="M150 225l390-25 35 50-390 30z"/><path d="M150 225v105l35 45v-95z"/><path d="M185 280l390-30v105l-390 30z"/></g><g fill="#bd975c" stroke="#967849" stroke-width="2"><rect x="245" y="120" width="60" height="125" rx="10"/><rect x="327" y="145" width="58" height="96" rx="10"/><rect x="415" y="110" width="60" height="125" rx="10"/></g><g fill="#455943"><rect x="240" y="112" width="70" height="19" rx="5"/><rect x="322" y="137" width="68" height="19" rx="5"/><rect x="410" y="102" width="70" height="19" rx="5"/></g><g fill="#b7bd9e" stroke="#899877" stroke-width="2"><rect x="250" y="320" width="65" height="65" rx="8"/><rect x="345" y="310" width="65" height="65" rx="8"/><rect x="445" y="300" width="65" height="65" rx="8"/></g><g fill="#eee5c8"><rect x="257" y="152" width="36" height="45" rx="3"/><rect x="339" y="174" width="34" height="35" rx="3"/><rect x="426" y="145" width="36" height="45" rx="3"/></g></svg>`;
