let initial={products:[],orders:[],activeOrderId:'',style:'minimal',color:'#087f5b',features:{dimensions:true,material:true},pages:['main','dimensions','material'],customPrompt:'',tickets:[],settings:{email:'',notifications:true},wallet:{tokens:0,ledger:[]},paused:false};
let currentUser=null,authReady=false,registrationOpen=true,aiConfigured=false,storageKey='catalog-local-v1:guest';
function loadLocalState(){try{return{...structuredClone(initial),...JSON.parse(localStorage.getItem(storageKey)||'{}')}}catch{return structuredClone(initial)}}
let state=loadLocalState();
let generatedImages={},generatedAssets={};let authMode='login';let screen='home',tab='main',currentProduct='',busy=false,progress=0,paymentAccepted=false;
async function apiRequest(path,options={}){let response;try{response=await fetch(path,{credentials:'same-origin',...options,headers:{...(options.headers||{}),...(options.body?{'Content-Type':'application/json'}:{})}})}catch{throw Error(location.protocol==='file:'?'Откройте сайт по адресу сервера, а не через файл index.html.':'Нет связи с сервером. Проверьте, включён ли ноутбук и работает ли сервер.')}if(!response.headers.get('content-type')?.includes('application/json'))throw Error('По этому адресу нет API сайта. Откройте сайт через сервер.');const data=await response.json().catch(()=>({}));if(!response.ok)throw Error(data.error||`Ошибка сервера ${response.status}`);return data}
async function refreshWallet(){if(!currentUser)return;try{const w=await apiRequest('/api/wallet');state.wallet={tokens:w.tokens,ledger:w.ledger.map(x=>({delta:x.delta,label:x.description,date:x.created_at,kind:x.kind}))};save()}catch(e){toast(e.message)}}
async function syncWorkspaceNow(){if(!currentUser)return;const {wallet,...workspace}=state;await apiRequest('/api/workspace',{method:'PUT',body:JSON.stringify({workspace})})}
async function loadWorkspace(){try{const data=await apiRequest('/api/workspace');if(data.workspace)state={...structuredClone(initial),...data.workspace,wallet:state.wallet};else await syncWorkspaceNow()}catch(e){toast('Не удалось загрузить каталог: '+e.message)}}
async function acceptAuth(mode,form){const fd=new FormData(form),email=String(fd.get('email')||'').trim(),password=String(fd.get('password')||'');try{const data=await apiRequest(mode==='register'?'/api/auth/register':'/api/auth/login',{method:'POST',body:JSON.stringify({email,password})});currentUser=data.user;storageKey='catalog-local-v1:'+currentUser.id;state=loadLocalState();state.settings.email=currentUser.email;state.wallet={tokens:currentUser.tokens,ledger:[]};authReady=true;await loadWorkspace();await refreshWallet();location.hash='home';render();toast(mode==='register'?'Аккаунт создан':'Вы вошли в аккаунт')}catch(e){toast(e.message)}}
async function bootstrapAuth(){try{const [data,health]=await Promise.all([apiRequest('/api/me'),apiRequest('/api/health').catch(()=>({registrationOpen:true}))]);registrationOpen=health.registrationOpen!==false;aiConfigured=Boolean(health.aiConfigured);if(!registrationOpen)authMode='login';currentUser=data.user;if(currentUser){storageKey='catalog-local-v1:'+currentUser.id;state=loadLocalState();state.settings.email=currentUser.email;state.wallet={tokens:currentUser.tokens,ledger:[]};await loadWorkspace();await refreshWallet()}}catch{}authReady=true;render()}let workspaceSyncTimer;function save(){try{const {wallet,...localState}=state;localStorage.setItem(storageKey,JSON.stringify(localState));if(currentUser){clearTimeout(workspaceSyncTimer);workspaceSyncTimer=setTimeout(()=>syncWorkspaceNow().catch(e=>toast('Каталог не синхронизирован: '+e.message)),700)}}catch{toast('Память браузера заполнена. Удалите лишние фото или скачайте архив.')}}let timer;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4200)}
function demo(){state.products=[{id:uid(),sku:'HOME-001',name:'Кухонный органайзер',dimensions:'30 × 20 × 15 см',material:'Пластик',description:'Органайзер для хранения кухонных принадлежностей.',photo:sample},{id:uid(),sku:'HOME-002',name:'Органайзер для специй',dimensions:'25 × 18 × 12 см',material:'Пластик',description:'Хранение специй и небольших банок.',photo:sample},{id:uid(),sku:'HOME-003',name:'Полка для кухни',dimensions:'',material:'Пластик',description:'Компактное хранение на кухне.',photo:sample}];save();toast('Загружены 3 демонстрационных товара. Иллюстрации условные.');go('upload')}
function go(v){if(busy && !['checkout','orders','admin','home'].includes(v)){toast('Дождитесь завершения сборки');return}location.hash=v;if(screen===v)render()}
function steps(n){return `<div class="steps" aria-label="Этапы создания карточек">${['Фото и товары','Проверка','Стиль','Сборка','Результат'].map((t,i)=>`<div class="step ${i<=n?'on':''} ${i===n?'current':''}" ${i===n?'aria-current="step"':''}><b>${i<n?icon('check'):i+1}</b><span>${t}</span></div>`).join('')}</div>`}
function heading(k,h,p,action=''){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${h}</h1><p class="muted">${p}</p></div>${action}</div>`}
function badge(t,w=false){return `<span class="tag ${w?'warn':''}"><span class="statusdot"></span>${t}</span>`}
function empty(){return `<div class="card empty">${icon('products')}<h3>Пока нет товаров</h3><p>Добавьте свои фото или изучите платформу на примере.</p><div class="row" style="justify-content:center;margin-top:20px"><button data-act="demo" class="primary">Загрузить пример</button><button data-go="upload">Добавить товары</button></div></div>`}
function shell(body){
 if(screen==='home')return `<main class="editorial-site">${body}</main>`;
 const nav=[['home','Главная'],['upload','Создать карточки','new'],['products','Мои товары'],['orders','Мои генерации'],['pricing','Баланс и токены','style'],['account','Мой аккаунт','settings'],['admin','Администрирование']].filter(([id])=>id!=='admin'||currentUser?.role==='admin');
 const names={home:'Главная',upload:'Добавление товаров',validate:'Проверка данных',style:'Выбор оформления',checkout:'Сборка карточек',result:'Готовые карточки',products:'Мои товары',orders:'Мои генерации',pricing:'Баланс и токены',account:'Мой аккаунт',help:'Помощь',admin:'Администрирование'};
 return `<div class="shell"><aside class="sidebar" id="studio-menu"><a href="#home" class="logo"><span class="mark">${icon('spark')}</span><span>Каталог<br>за вечер<small>СТУДИЯ ИНФОГРАФИКИ</small></span></a><div class="nav-caption">ВАША СТУДИЯ</div><nav class="nav" aria-label="Основная навигация">${nav.map(([id,t,ic])=>{const active=screen===id||id==='upload'&&['validate','style','checkout','result'].includes(screen);return `<a href="#${id}" class="${active?'active':''} ${id==='upload'?'nav-create':''}" ${active?'aria-current="page"':''}>${icon(ic||id)}${t}${id==='products'?`<span class="badgecount">${state.products.length}</span>`:''}</a>`}).join('')}</nav><div class="sidebottom"><div class="sidebox"><span class="sidebox-icon">${icon('spark')}</span><strong>Начните с примера</strong><small>Посмотрите, как устроена студия</small><button class="small" data-act="demo">Открыть пример ${icon('arrow')}</button></div><a class="help-link" href="#help">${icon('help')}Помощь и настройки</a><a class="user" href="#account"><span class="avatar">${esc((currentUser?.email||'U').slice(0,1).toUpperCase())}</span><span class="user-info"><strong>${esc(currentUser?.email||'Аккаунт')}</strong><small>${currentUser?.role==='admin'?'Администратор':'Личный аккаунт'}</small></span></a><button class="small logout" data-act="logout">Выйти из аккаунта</button></div></aside><main><header class="topbar"><div class="row"><button class="mobilemenu small" data-act="menu" aria-label="Открыть меню" aria-controls="studio-menu" aria-expanded="false">☰</button><span class="breadcrumb">Студия <span>/</span> <strong>${names[screen]||'Главная'}</strong></span></div><a href="#pricing" class="balance-link" aria-label="Баланс: ${state.wallet?.tokens||0} токенов. Открыть пополнение">${icon('spark')} <strong>${state.wallet?.tokens||0}</strong> <span>токенов</span><span class="balance-plus">+</span></a></header><div class="content" data-screen="${screen}">${body}</div></main></div>`;
}
function home(){
 const tokens=state.wallet?.tokens||0;
 return `<section class="ed-hero"><img class="ed-hero-photo" src="/studio-hero.png" alt="Дизайнерское кресло в интерьере на фоне леса"><div class="ed-shade"></div><header class="ed-header"><a class="ed-brand" href="#home"><span class="ed-symbol">${icon('spark')}</span><span>Каталог <em>за вечер</em></span></a><nav aria-label="Навигация студии"><a href="#upload">Создать карточки</a><a href="#orders">Мои генерации</a><a href="#help">Помощь</a></nav><a class="ed-account" href="#account">Мой кабинет <span>↗</span></a></header><div class="ed-hero-content"><span class="ed-kicker">ВЫ ЗАДАЁТЕ ИДЕЮ. НЕЙРОСЕТЬ СОЗДАЁТ.</span><h1>У вашего товара<br>есть <em>характер.</em></h1><p>Покажите его. Создавайте выразительные карточки<br class="desktop-break"> по фотографии и вашим пожеланиям.</p><div class="ed-hero-actions"><button class="primary" data-go="upload">Создать карточки <span class="button-orb">↗</span></button><button class="ed-text-button" data-act="demo"><span class="ed-play">${icon('arrow')}</span>Открыть пример</button></div><div class="ed-hero-facts"><span>${icon('upload')} Ваше фото<br>и характеристики</span><span>${icon('style')} Ваш стиль<br>и пожелания</span><span>${icon('download')} Готовые карточки<br>одним архивом</span></div></div><aside class="ed-glass"><div class="ed-glass-top"><span class="ed-tiny">ТВОРЧЕСТВО БЕЗ ЛИШНЕЙ РУТИНЫ</span><span class="ed-glass-symbol">✳</span></div><h2>Из обычного фото —<br>в историю товара.</h2><p>Нейросеть создаёт весь кадр:<br>композицию, фон и надписи.</p><a href="#upload" aria-label="Перейти к созданию карточек">Начать с моего товара <span>↗</span></a></aside><div class="ed-hero-bottom"><span>СТУДИЯ ИНФОГРАФИКИ / 01</span><a href="#pricing">1 карточка · 10 ₽ <span>↗</span></a><span class="ed-scroll">ДАЛЬШЕ — ПРОЩЕ ↓</span></div></section><section class="ed-process"><div class="ed-section-label">(01)<span>ОТ ФОТО К РЕЗУЛЬТАТУ</span></div><div class="ed-process-intro"><h2>Хороший дизайн.<br><em>Простой процесс.</em></h2><p>Вам не нужно разбираться в редакторах.<br>Достаточно знать свой товар и то,<br>каким вы хотите его показать.</p></div><div class="ed-process-steps"><article><span class="ed-number">01</span><h3>Добавьте товар</h3><p>Загрузите фото, название и характеристики. Один товар или сразу несколько.</p><button class="ed-inline" data-go="upload">Добавить фото ${icon('arrow')}</button></article><article><span class="ed-number">02</span><h3>Задайте настроение</h3><p>Выберите оформление и нужные слайды. Опишите свою идею в поле пожеланий.</p><span class="ed-step-caption">Стиль · цвет · ваш промпт</span></article><article><span class="ed-number">03</span><h3>Заберите результат</h3><p>Проверьте сходство товара и надписи. Скачайте изображения по одному или архивом.</p><a class="ed-inline" href="#orders">Мои генерации ${icon('arrow')}</a></article></div></section><section class="ed-direction"><div class="ed-direction-copy"><div class="ed-section-label">(02)<span>ВЫБИРАЕТЕ ВЫ</span></div><h2>Один товар.<br><em>Ваш взгляд.</em></h2><p>Спокойный минимализм или смелый акцент.<br>Выберите стиль и расскажите, что для вас важно.<br>Каждая карточка начинается с вашей идеи.</p><div class="ed-style-list"><span>01 / Минимализм</span><span>02 / Натуральный</span><span>03 / Контрастный</span></div><button class="ed-light-button" data-go="upload">Попробовать со своим фото <span>↗</span></button></div><div class="ed-idea-panel"><span class="ed-tiny">ВАШИ ПОЖЕЛАНИЯ К КАРТОЧКЕ</span><span class="ed-quote">“</span><p>Мягкий дневной свет.<br>Природные материалы.<br><em>Всё внимание — товару.</em></p><div class="ed-idea-tags"><span>Фото товара</span><span>Стиль</span><span>Ваш промпт</span></div><small>Пример пожеланий, которые можно задать при сборке</small></div></section><section class="ed-start"><div><div class="ed-section-label">(03)<span>НАЧНИТЕ С ОДНОЙ КАРТОЧКИ</span></div><h2>Пусть ваш товар<br><em>говорит за себя.</em></h2><p>Баланс вашего аккаунта — ${tokens} ${plural(tokens,'токен','токена','токенов')}.<br>Одна выбранная страница товара — одна генерация.</p><button class="primary" data-go="upload">Создать первую карточку <span class="button-orb">↗</span></button></div><div class="ed-price"><span>ОДНА ГЕНЕРАЦИЯ</span><strong>10 <em>₽</em></strong><p>1 токен = 1 карточка</p><a href="#pricing">Баланс и тестовые пакеты <span>↗</span></a></div></section><footer class="ed-footer"><a href="#home" class="ed-brand">${icon('spark')} Каталог за вечер</a><span>Ваш товар. Ваша идея. Наши инструменты.</span><a href="#account">Личный кабинет ↗</a></footer>`;
}
function productTable(validation=false){return `<div class="tablewrap"><table><thead><tr><th>Товар</th><th>Размеры</th><th>Материал</th><th>Проверка</th><th></th></tr></thead><tbody>${state.products.map(p=>`<tr><td><div class="productcell"><img class="thumb" src="${p.photo||sample}" alt=""><div><strong>${esc(p.name)}</strong><small>${esc(p.sku)}</small></div></div></td><td>${esc(p.dimensions)||'<span class="error">Не указаны</span>'}</td><td>${esc(p.material)||'—'}</td><td>${issues(p).length?badge(issues(p).join(', '),true):badge('Данные заполнены')}</td><td><button class="small" data-edit="${p.id}">Изменить</button></td></tr>`).join('')}</tbody></table></div>`}
function issues(p){let a=[];if(!p.name.trim())a.push('Название');if(!p.photo)a.push('Нет фото');if(!p.dimensions.trim())a.push('Размеры');if(!p.material.trim())a.push('Материал');if(state.products.some(q=>q.id!==p.id&&q.sku===p.sku))a.push('Артикул повторяется');return a}
function upload(){return heading('Новый каталог','Начнём с ваших товаров','Добавьте фотографии и характеристики. Или загрузите пример.',`<button data-act="demo">Заполнить примером</button>`)+steps(0)+`<div class="grid two"><label class="upload" id="drop">${icon('upload')}<strong>Фотографии товаров</strong><small>PNG, JPG, WebP · до 10 МБ на фото · до 30 товаров</small><input id="photos" type="file" accept="image/png,image/jpeg,image/webp" multiple></label><label class="upload">${icon('orders')}<strong>Таблица характеристик</strong><small>XLSX или CSV · первая строка — названия столбцов</small><input id="sheet" type="file" accept=".csv,.xlsx"><button type="button" class="small" data-act="template" style="margin-top:10px">Скачать пример CSV</button></label></div><div class="card section"><div class="row between" style="margin-bottom:18px"><h3>Ваши товары <span class="muted">${state.products.length}</span></h3><button class="small" data-act="add">Добавить вручную</button></div>${state.products.length?productTable():`<div class="empty"><h3>Здесь появится ваш каталог</h3><p>Имя фото сопоставляется с артикулом из таблицы.</p></div>`}</div><div class="actions"><span class="muted">Каталог синхронизируется с вашим аккаунтом.</span><button class="primary" data-act="validate">Проверить каталог ${icon('arrow')}</button></div>`}
function validate(){if(!state.products.length)return empty();const n=state.products.filter(p=>issues(p).length).length;return heading('Шаг 2 из 5','Проверим детали','Исправьте пропуски, чтобы карточки содержали верную информацию.')+steps(1)+`<div class="notice">${n?`Товаров с пропусками: ${n}. Исправьте данные через «Изменить».`:'Все обязательные поля заполнены. Можно переходить к оформлению.'} Проверка сверяет заполненность, но не подтверждает достоверность свойств.</div><div class="card flush">${productTable(true)}</div><div class="actions"><button data-go="upload">Назад к загрузке</button><button class="primary" data-act="to-style">Выбрать оформление ${icon('arrow')}</button></div>`}
const styles=[['minimal','Минимализм','Светлый фон и спокойная типографика.'],['natural','Натуральный','Тёплая палитра и мягкие оттенки.'],['bold','Контрастный','Тёмный фон и выразительные акценты.']];
const pageTypes=[['main','Главная'],['dimensions','Размеры'],['material','Материал'],['benefits','Преимущества'],['composition','Состав'],['design','Дизайн'],['convenience','Удобство']];
function style(){if(!state.products.length)return empty();return heading('Шаг 3 из 5','Как будут выглядеть карточки?','Выберите стиль для нейросети. Примеры ниже схематичные; готовую карточку целиком создаст AI.')+steps(2)+`<div class="grid three">${styles.map(([id,t,d])=>`<button class="card stylecard ${state.style===id?'selected':''}" data-style="${id}" aria-pressed="${state.style===id}"><img id="style-${id}" alt="Пример стиля ${t}"><h3>${t}</h3><p>${d}</p></button>`).join('')}</div><div class="card section"><div class="row between"><div><h3>Детали оформления</h3><p class="muted">Только подтверждённые характеристики</p></div><label class="row">Цвет бренда <input type="color" id="brand-color" value="${state.color}"></label></div><div class="row" style="margin-top:20px"><label class="row"><input type="checkbox" data-feature="dimensions" ${state.features.dimensions?'checked':''}>Размеры</label><label class="row"><input type="checkbox" data-feature="material" ${state.features.material?'checked':''}>Материал</label></div></div><div class="actions"><button data-go="validate">Назад</button><button class="primary" data-go="checkout">Выбрать страницы ${icon('arrow')}</button></div>`}
function checkout(){if(!state.products.length)return empty();state.pages=Array.isArray(state.pages)&&state.pages.length?state.pages:['main','dimensions','material'];const tokens=state.wallet?.tokens||0,selected=pageTypes.filter(([id])=>state.pages.includes(id)),total=state.products.length*selected.length;return heading('Шаг 4 из 5','Выберите страницы карточки','Отметьте, какие слайды нужны для каждого товара.')+steps(3)+`<div class="notice">Каждая выбранная страница считается отдельной генерацией: 1 страница × 1 товар = 1 токен (10 ₽). Главная страница включена всегда.</div><div class="card prompt-card"><div class="row between"><div><h2>Ваш промпт для нейросети</h2><p class="muted" id="custom-prompt-help">Опишите желаемую композицию, фон, освещение, надписи и дополнительные детали. Пожелания будут учтены на всех выбранных страницах этой сборки.</p></div><span class="tag">Необязательно</span></div><label class="field section" for="custom-prompt">Личные пожелания<textarea id="custom-prompt" maxlength="2000" rows="5" aria-describedby="custom-prompt-help custom-prompt-count" placeholder="Например: светлая кухня, тёплый дневной свет, бежевые оттенки, минималистичный фон без лишних деталей." ${busy?'disabled':''}>${esc(state.customPrompt||'')}</textarea></label><div class="row between prompt-footer"><span class="caption" id="custom-prompt-count">${(state.customPrompt||'').length} / 2000 символов</span><button type="button" class="small" id="clear-custom-prompt" ${busy||!state.customPrompt?'disabled':''}>Очистить пожелания</button></div><p class="caption">Можно оставить поле пустым — нейросеть использует выбранный стиль и характеристики товара.</p></div><div class="grid two"><div class="card"><h2>Какие страницы создать?</h2><p class="muted">Для слайдов с преимуществами, составом, дизайном и удобством укажите подтверждённые сведения в описании товара.</p><div class="page-options section">${pageTypes.map(([id,label])=>`<label class="page-option"><input type="checkbox" data-page="${id}" ${state.pages.includes(id)?'checked':''} ${id==='main'?'disabled':''}><span><strong>${label}</strong><small>${id==='main'?'Основной слайд с фото и названием':id==='dimensions'?'Габариты товара':id==='material'?'Материал изделия':'Будет сформировано по описанию товара'}</small></span></label>`).join('')}</div><div class="lineitem"><span>Товаров</span><strong>${state.products.length}</strong></div><div class="lineitem"><span>Страниц на товар</span><strong>${selected.length}</strong></div><div class="lineitem"><span>Всего генераций</span><strong>${total} токенов · ${total*10} ₽</strong></div><div class="lineitem"><span>Ваш баланс</span><strong>${tokens} токенов</strong></div><label class="row"><input id="accept" type="checkbox" ${paymentAccepted?'checked':''}>Я проверил фото и характеристики</label><button class="primary" style="width:100%;margin-top:22px" data-act="generate" ${busy?'disabled':''}>${busy?'Идёт сборка…':`Создать ${total} ${plural(total,'карточку','карточки','карточек')} · ${total} ${plural(total,'токен','токена','токенов')}`}</button><a class="small section" href="#pricing">Пополнить баланс</a></div><div class="card"><div class="eyebrow">Предпросмотр состава</div><h2>${selected.length} страницы на товар</h2><div class="page-preview-list section">${selected.map(([id,label],i)=>`<div class="lineitem"><span>${String(i+1).padStart(2,'0')} · ${label}</span><strong>1 токен</strong></div>`).join('')}</div><p class="muted">Баланс хранится в аккаунте. За каждую успешно созданную страницу списывается один токен; при ошибке генерации токен возвращается.</p><div class="progress"><div id="progress" style="width:${progress}%"></div></div><p id="progress-text">${busy?`${progress}%`:progress===100?'Готово. Перейдите к результатам.':'Ожидает запуска'}</p></div></div>`}
function result(){
  const order=currentResultOrder(),products=currentResultProducts();
  if(!products.length)return empty();
  const p=products.find(item=>item.id===currentProduct)||products[0],pages=pageTypes.filter(([id])=>(order?.pages||state.pages||['main']).includes(id));
  currentProduct=p.id;if(!pages.some(([id])=>id===tab))tab=pages[0]?.[0]||'main';
  const ready=Boolean(order?.assets?.[`${p.id}:${tab}`]),hasAny=Boolean(Object.keys(order?.assets||{}).length),full=order?.renderMode==='full-card';
  return heading('Шаг 5 из 5','Ваш каталог готов к просмотру','Проверьте изображения и скачайте результат.',`<button class="primary" data-act="download" ${hasAny?'':'disabled'}>${icon('download')} Скачать ZIP</button>`)+steps(4)+`<div class="split"><div class="card"><div class="row between" style="margin-bottom:18px"><span class="previewlabel">${full?'Готовая AI-карточка':'Ранее созданная карточка'} · ${pageTypes.find(([id])=>id===tab)?.[1]||'Карточка'}</span><button class="small" data-act="png" ${ready?'':'disabled'}>Скачать изображение</button></div><div id="result-empty" class="empty" hidden></div><img id="result-preview" class="preview" alt="Готовая карточка товара"><div class="gallery">${pages.map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'selected':''}" ${order?.assets?.[`${p.id}:${id}`]?'':'disabled'}><img id="gallery-${id}" alt="${label}"><small>${label}</small></button>`).join('')}</div></div><div><div class="card"><label class="field">Товар<select id="result-product">${products.map(item=>`<option value="${item.id}" ${item.id===p.id?'selected':''}>${esc(item.name)}</option>`).join('')}</select></label><div class="section"><h3>${esc(p.name)}</h3><p class="muted">${esc(p.sku)}</p></div><div class="lineitem"><span>Размеры</span><strong>${esc(p.dimensions)}</strong></div><div class="lineitem"><span>Материал</span><strong>${esc(p.material)}</strong></div><p>${esc(p.description)||esc(description(p))}</p>${order?.customPrompt?`<p class="caption"><strong>Пожелания этой сборки:</strong> ${esc(order.customPrompt)}</p>`:''}<button style="margin-top:22px" data-go="upload">Изменить данные для новой сборки</button></div><div class="card section compare"><div class="previewlabel">Фото, переданное для этой сборки</div><img src="${p.photo||sample}" alt="Исходное фото товара"></div><p class="caption">${full?'Вся карточка создана нейросетью: товар, фон, композиция и надписи. Сайт показывает и скачивает готовый файл без наложений. Проверьте текст и сходство товара перед публикацией.':'Эта сборка создана прежним способом: AI-фон и шаблонные наложения. Для полностью сгенерированной карточки выполните новую сборку.'}</p><button class="small section" data-go="style">Выбрать оформление для новой сборки</button></div></div>`;
}

function products(){return heading('Библиотека','Мои товары','Исходники и характеристики вашего текущего каталога.',`<button class="primary" data-go="upload">${icon('new')} Добавить товары</button>`)+(state.products.length?`<div class="card flush">${productTable()}</div><div class="actions"><button data-act="clear" class="danger">Очистить каталог</button><button data-go="style">Оформить каталог ${icon('arrow')}</button></div>`:empty())}
