async function sourcePhoto(photo){
  if(typeof photo!=='string'||!photo)throw Error('Добавьте фото товара');
  if(photo!==sample)return photo;
  const image=await new Promise((resolve,reject)=>{const item=new Image;item.onload=()=>resolve(item);item.onerror=reject;item.src=photo});
  const canvas=document.createElement('canvas');canvas.width=image.width;canvas.height=image.height;canvas.getContext('2d').drawImage(image,0,0);
  return canvas.toDataURL('image/png');
}
async function generate(){
  if(busy)return;
  if(state.paused)return toast('Новые генерации приостановлены в панели администратора');
  if(!state.products.length)return toast('Добавьте товары');
  if(state.products.some(p=>issues(p).length))return toast('Заполните все поля и добавьте фото на шаге проверки');
  if(!paymentAccepted)return toast('Подтвердите проверку фото и характеристик');
  const pages=pageTypes.filter(([id])=>(state.pages||[]).includes(id)).map(([id])=>id);
  if(!pages.length)return toast('Выберите хотя бы одну страницу');
  const cost=state.products.length*pages.length;
  if((state.wallet?.tokens||0)<cost)return toast(`Недостаточно токенов: нужно ${cost}. Пополните баланс.`);
  busy=true;progress=0;render();
  const snapshot=structuredClone(state.products);
  const settings={style:state.style,color:state.color,features:structuredClone(state.features),pages,customPrompt:(state.customPrompt||'').trim()};
  const total=snapshot.length*pages.length,orderAssets={};
  const order={id:Date.now().toString(36)+Math.random().toString(36).slice(2,6),date:new Date().toISOString(),products:snapshot,...settings,renderMode:'full-card',assets:orderAssets};
  let done=0,orderSaved=false;
  try{
    for(const p of snapshot){
      const photo=await sourcePhoto(p.photo);
      for(const page of pages){
        if($('#progress-text'))$('#progress-text').textContent=`Нейросеть создаёт всю страницу «${pageTypes.find(([id])=>id===page)?.[1]||page}» для ${p.name}. Фото и готовая карточка проходят проверку безопасности. Это может занять несколько минут.`;
        const response=await fetch('/api/generate-image',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name:p.name,sku:p.sku,material:p.material,dimensions:p.dimensions,description:p.description,photo,page,style:settings.style,color:settings.color,features:settings.features,customPrompt:settings.customPrompt}),signal:AbortSignal.timeout(780000)});
        const result=await response.json().catch(()=>({}));
        if(!response.ok)throw Error(result.error||`Ошибка API: ${response.status}`);
        if(result.renderMode!=='full-card'||!result.generationId||!result.imageData)throw Error('Сервер не вернул готовую AI-карточку. Обновите страницу и повторите попытку.');
        state.wallet.tokens=result.tokens;
        generatedImages[result.generationId]={url:result.imageData,mode:'full-card',mime:result.imageData.slice(5,result.imageData.indexOf(';'))};
        generatedAssets[`${p.id}:${page}`]=result.generationId;orderAssets[`${p.id}:${page}`]=result.generationId;
        if(!orderSaved){state.orders.unshift(order);state.activeOrderId=order.id;orderSaved=true}
        order.assets={...orderAssets};save();
        progress=Math.round(++done/total*100);
        if($('#progress'))$('#progress').style.width=progress+'%';
        if($('#progress-text'))$('#progress-text').textContent=`Готово ${done} из ${total} страниц`;
      }
    }
    await refreshWallet();busy=false;go('result');toast('Готовые AI-карточки сохранены. Токены списаны за успешные страницы.');
  }catch(error){
    await refreshWallet();busy=false;
    if(orderSaved){save();go('result');toast(`Сборка завершилась частично: ${done} из ${total} страниц готовы. ${error.message}`)}
    else{render();toast('Генерация не выполнена: '+error.message)}
  }
}

