const csvCell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';
async function exportZip(selectedOrder){
  toast('Подготавливаю архив…');
  const order=selectedOrder||currentResultOrder();
  if(!order)return toast('Сначала сгенерируйте карточки');
  const data=order.products,pages=order.pages||['main'];
  try{
    const files=[],missing=[];let images=0;
    for(const[idx,p]of data.entries()){
      const folder=String(idx+1).padStart(2,'0')+'-'+p.sku.replace(/[^\p{L}\p{N}_-]/gu,'_').slice(0,60);
      for(const page of pages){
        const label=pageTypes.find(([id])=>id===page)?.[1]||page;
        if(!order.assets?.[`${p.id}:${page}`]){missing.push(`${p.sku} / ${label}`);continue}
        const uri=await pageImage(p,page,order),blob=await(await fetch(uri)).blob();
        files.push({name:`${folder}/${page}-${label}.${imageExtension(blob.type)}`,data:new Uint8Array(await blob.arrayBuffer())});images++;
      }
      files.push({name:folder+'/description.txt',data:p.description||description(p)});
    }
    if(!images)throw Error('В этой сборке нет сохранённых изображений. Запустите новую сборку.');
    files.push({name:'products.csv',data:'\uFEFF'+[['Артикул','Название','Размеры','Материал','Описание'],...data.map(p=>[p.sku,p.name,p.dimensions,p.material,p.description||description(p)])].map(row=>row.map(csvCell).join(';')).join('\r\n')});
    if(order.customPrompt)files.push({name:'prompt.txt',data:order.customPrompt});
    files.push({name:'README.txt',data:'Каталог за вечер.\n'+(order.renderMode==='full-card'?'Карточки полностью созданы нейросетью по исходным фото, характеристикам, стилю и пожеланиям. Готовые изображения сохранены без наложений сайта.':'Старая сборка: AI-фоны с шаблонными наложениями.')+'\nПроверьте сходство товара, текст и характеристики перед размещением.'+(missing.length?'\nНе были сгенерированы и не включены в архив:\n'+missing.join('\n'):'')});
    download('catalog-'+order.id+'.zip',zip(files));toast(missing.length?'Архив готов. Включены только успешно сгенерированные страницы.':'Архив готов');
  }catch(error){toast('Не удалось собрать архив: '+error.message)}
}

function bind(){if($('#auth-form'))$('#auth-form').onsubmit=e=>{e.preventDefault();acceptAuth(authMode,e.currentTarget)};$$('[data-auth-mode]').forEach(b=>b.onclick=()=>{authMode=b.dataset.authMode;render()});if($('#admin-users-table'))loadAdmin(); $$('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));$$('[data-edit]').forEach(b=>b.onclick=()=>edit(b.dataset.edit));$$('[data-style]').forEach(b=>b.onclick=()=>{state.style=b.dataset.style;save();render()});$$('[data-result-style]').forEach(b=>b.onclick=()=>{state.style=b.dataset.resultStyle;save();render()});$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});$$('[data-page]').forEach(e=>e.onchange=()=>{const pages=state.pages||['main','dimensions','material'];state.pages=e.checked?[...new Set([...pages,e.dataset.page])]:pages.filter(p=>p!==e.dataset.page);if(!state.pages.length)state.pages=['main'];save();render()});$$('[data-order]').forEach(b=>b.onclick=()=>exportZip(state.orders.find(o=>o.id===b.dataset.order)));$$('[data-close-ticket]').forEach(b=>b.onclick=()=>{state.tickets.find(t=>t.id===b.dataset.closeTicket).closed=true;save();render()});$$('[data-act]').forEach(b=>b.onclick=async e=>{const a=b.dataset.act;if(a==='buy-tokens'){try{const data=await apiRequest('/api/test/topup',{method:'POST',body:JSON.stringify({tokens:Number(b.dataset.tokens)})});state.wallet.tokens=data.tokens;await refreshWallet();render();toast('Тестовые токены начислены. Оплата не проводилась.')}catch(e){toast(e.message)}}if(a==='logout'){try{await apiRequest('/api/auth/logout',{method:'POST',body:'{}'})}catch{}currentUser=null;storageKey='catalog-local-v1:guest';state=structuredClone(initial);authMode='login';location.hash='home';render()}if(a==='admin-refresh')loadAdmin();if(a==='demo'){if(state.products.length&&!confirm('Заменить текущий каталог демонстрационными товарами? Сборки в истории сохранятся.'))return;demo()}if(a==='menu'){const open=$('.sidebar').classList.toggle('open');b.setAttribute('aria-expanded',String(open))};if(a==='template'){e.preventDefault();download('catalog-template.csv','\uFEFFАртикул;Название;Размеры;Материал;Описание\r\nHOME-001;Кухонный органайзер;30 × 20 × 15 см;Пластик;Органайзер для кухни','text/csv;charset=utf-8')}if(a==='add'){if(state.products.length>=30)return toast('Максимум 30 товаров');let p={id:uid(),sku:'ITEM-'+(state.products.length+1),name:'Новый товар',dimensions:'',material:'',description:'',photo:''};state.products.push(p);save();render();edit(p.id)}if(a==='validate'){if(!state.products.length)return toast('Сначала добавьте товары');go('validate')}if(a==='to-style'){if(state.products.some(p=>issues(p).length))return toast('Исправьте пропуски и повторяющиеся артикулы');go('style')}if(a==='generate')generate();if(a==='download')exportZip();if(a==='png')downloadCurrentImage();if(a==='clear'&&confirm('Очистить текущий каталог? История сохранится.')){state.products=[];save();render()}if(a==='settings'){if(!$('#email').checkValidity())return $('#email').reportValidity();state.settings={email:$('#email').value,notifications:$('#notifications').checked};save();toast('Настройки сохранены локально')}if(a==='reset'&&confirm('Удалить товары, историю, обращения и настройки из этого браузера?')){localStorage.removeItem('catalog-local-v1');state=structuredClone(initial);paymentAccepted=false;go('home');toast('Локальные данные удалены')}});
 if($('#photos'))$('#photos').onchange=e=>addPhotos([...e.target.files]);if($('#sheet'))$('#sheet').onchange=e=>readSheet(e.target.files[0]);if($('#drop')){const d=$('#drop');d.ondragover=e=>{e.preventDefault();d.classList.add('drag')};d.ondragleave=()=>d.classList.remove('drag');d.ondrop=e=>{e.preventDefault();d.classList.remove('drag');addPhotos([...e.dataTransfer.files])}}
 if($('#custom-prompt')){const input=$('#custom-prompt'),clear=$('#clear-custom-prompt');const remember=()=>{state.customPrompt=input.value.slice(0,2000);$('#custom-prompt-count').textContent=state.customPrompt.length+' / 2000 символов';clear.disabled=busy||!state.customPrompt;save()};input.oninput=remember;clear.onclick=()=>{input.value='';remember();input.focus()}}
 if($('#brand-color'))$('#brand-color').oninput=e=>{state.color=e.target.value;save();paintPreviews()};$$('[data-feature]').forEach(e=>e.onchange=()=>{state.features[e.dataset.feature]=e.checked;save();paintPreviews()});if($('#accept'))$('#accept').onchange=e=>paymentAccepted=e.target.checked;if($('#result-product'))$('#result-product').onchange=e=>{currentProduct=e.target.value;render()};if($('#paused'))$('#paused').onchange=e=>{state.paused=e.target.checked;save();toast(state.paused?'Новые сборки приостановлены':'Сборки разрешены')};if($('#support'))$('#support').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),msg=fd.get('message').trim();if(msg.length<5)return toast('Опишите проблему подробнее');state.tickets.push({id:uid(),date:new Date().toISOString(),order:fd.get('order').trim(),message:msg,closed:false});save();render();toast('Обращение сохранено локально')};}
window.addEventListener('hashchange',render);bootstrapAuth();

async function xlsxLocal(file){
 const bytes=new Uint8Array(await file.arrayBuffer()),v=new DataView(bytes.buffer);let end=-1;for(let i=bytes.length-22;i>=Math.max(0,bytes.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('Некорректный XLSX');const files={};let pos=v.getUint32(end+16,true);const count=v.getUint16(end+10,true);for(let i=0;i<count;i++){if(v.getUint32(pos,true)!==0x02014b50)throw Error('Повреждён архив');let method=v.getUint16(pos+10,true),size=v.getUint32(pos+20,true),nl=v.getUint16(pos+28,true),ex=v.getUint16(pos+30,true),cl=v.getUint16(pos+32,true),off=v.getUint32(pos+42,true);let name=new TextDecoder().decode(bytes.slice(pos+46,pos+46+nl));if(name==='xl/sharedStrings.xml'||name==='xl/worksheets/sheet1.xml'){let start=off+30+v.getUint16(off+26,true)+v.getUint16(off+28,true);let raw=bytes.slice(start,start+size);if(method===8){raw=new Uint8Array(await new Response(new Blob([raw]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer())}else if(method!==0)throw Error('Неподдерживаемое сжатие');files[name]=new DOMParser().parseFromString(new TextDecoder().decode(raw),'application/xml')}pos+=46+nl+ex+cl}
 const shared=[...(files['xl/sharedStrings.xml']?.getElementsByTagName('si')||[])].map(n=>n.textContent);const sheet=files['xl/worksheets/sheet1.xml'];if(!sheet)throw Error('Первый лист не найден');return [...sheet.getElementsByTagName('row')].map(r=>{let row=[];for(const c of r.getElementsByTagName('c')){let col=(c.getAttribute('r')||'A').replace(/[0-9]/g,''),idx=0;for(const ch of col)idx=idx*26+ch.charCodeAt(0)-64;while(row.length<idx)row.push('');let val=c.getElementsByTagName('v')[0]?.textContent||'';row[idx-1]=c.getAttribute('t')==='s'?shared[+val]:c.getAttribute('t')==='inlineStr'?(c.getElementsByTagName('is')[0]?.textContent||''):val}return row});
}

